"""Loci of points: both directions, the empty/one-point cases and the printed parameter signs."""
import argparse
import json
from circle_equations import make
from circle_line_positions import picture
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/coordinate-loci.json'


def frame(label,points,*,line=None,circle=None,edges=()):
    circles=[circle] if circle else []
    return picture(label,circles,points,line,edges)


def entry(n,*,part=None,pages=(267,),model_note=None,**fields):
    card=make(n,part=part,pages=pages,**fields)
    card['help'][1].update(theoryIds=['atanasyan-7-9-theory-97-part-1','atanasyan-7-9-theory-95-part-1','atanasyan-7-9-theory-98-part-1'],text='Перепиши условие на расстояния в координатах. Проверь обе стороны: каждая подходящая точка лежит на найденной фигуре, а каждая точка фигуры удовлетворяет исходному условию.')
    card['review']['reviewer']='Атанасян 7–9, 2023, печатные с. 265–267; для №1070–1075 учтены ответы с. 398–399, для №1069 и 1072 — печатные выводы. Проверены вырождения, знаки разностей и принадлежность точек в обе стороны.'
    card['visualization']['caption']=model_note or 'На модели показан численный пример. Сравни расстояния у отмеченных точек и затем проверь общее рассуждение для произвольной точки M.';card['visualization']['model']['description']=card['visualization']['caption'];return card


def apollonius():
    ab={'A':(0,0),'B':(3,0)};m={**ab,'M':(4,2)};initial=frame('Две заданные точки',ab);source=frame('Измерь AM и BM',m,edges=[('A','M'),('B','M')]);circle=frame('Все решения при AB=3',{**m,'P':(2,0),'Q':(6,0)},circle=('C',(4,0),4),edges=[('A','M'),('B','M')]);scale=frame('Новая длина AB=6',{'A':(0,0),'B':(6,0),'M':(8,4)},circle=('C',(8,0),16),edges=[('A','M'),('B','M')]);equal=frame('Другой вопрос: расстояния равны',{'A':(0,0),'B':(4,0),'M':(2,2)},line=(1,0,-2),edges=[('A','M'),('B','M')]);
    card=entry(1069,pages=(265,266,267),question='Для двух различных точек A и B найди все M, для которых AM=2BM. Определи центр и радиус через AB и докажи, что нашёл всё множество.',answer='Пусть A=(0;0), B=(a;0), a=AB>0. Получаем окружность (x−4a/3)²+y²=(2a/3)². Центр C на луче AB за B, AC=4AB/3; радиус 2AB/3. Уравнение равносильно исходному отношению.',hint='Возведение в квадрат сохраняет равносильность, потому что обе длины неотрицательны. Затем выдели полный квадрат по x.',steps=[('Запиши условие для произвольной точки','При A=(0;0), B=(a;0), M=(x;y) равенство AM=2BM равносильно x²+y²=4((x−a)²+y²). Например, при a=3 точка (4;2) даёт 20=4·5.','Два неотрицательных числа равны тогда и только тогда, когда равны их квадраты.'),('Определи всю фигуру','Раскрываем скобки: 3x²−8ax+3y²+4a²=0. Деление на 3 и выделение квадрата дают (x−4a/3)²+y²=4a²/9. Все преобразования обратимы, поэтому любая точка этой окружности действительно даёт AM=2BM.','Центр задан координатами, обращающими круглые скобки в ноль. Радиус — положительный корень из правой части.'),('Смени размер и сравни с равенством','При AB=6 получаем AC=8, r=4. Если же требуется уже AM=BM, квадраты x²+y² и (x−a)²+y² равны при x=a/2: это серединный перпендикуляр. Разные отношения задают разные фигуры.','Новая длина AB масштабирует исходную окружность. Замена множителя 2 на 1 меняет тип множества.')],frames=[initial,source,circle,scale],cases=[source,circle,scale,equal],prompts=[('При AB=3 найди абсциссу центра искомой окружности.','4','Умножь AB на 4/3.'),('При новой длине AB=6 и том же условии AM=2BM каков радиус?','4','Радиус равен 2AB/3, а не AC.')]);card['answer']=dict(mode='exact',accepted=['4/3;2/3','4/3; 2/3','4/3 и 2/3','4/3, 2/3'],prompt='Для центра C на луче AB и радиуса r введи через точку с запятой отношения AC/AB и r/AB.',feedback='После выделения квадрата центр имеет абсциссу 4a/3; справа 4a²/9, где a=AB. При нахождении радиуса извлеки корень.');return card


def weighted_sums():
    rows=[]
    for part in 'аб':
        small=part=='б';s=3 if small else 1;base={'A':(-s,0),'B':(0,0),'C':(s,0)};probe={**base,'M':((1,1) if small else (0,4))};center=(1,0) if small else (0,0);q=1 if small else 16
        init=frame('B — середина AC',base,edges=[('A','B'),('B','C')]);dists=frame('Расстояния до трёх фиксированных точек',probe,edges=[('A','M'),('B','M'),('C','M')]);full=frame('Все подходящие точки',probe,circle=('D',center,q),edges=[('D','M')]);new=frame('Измени правую часть',({**base,'M':(1,2)} if small else {**base,'M':(0,0)}),circle=('D',(1,0),4) if small else None)
        if small:
            eq='AM²+2BM²+3CM²=4';expr='6(x²+y²)−4x+4';reason='Получается 6(x²+y²)−4x+4=4. Делим на 6 и дополняем квадрат: (x−1/3)²+y²=1/9. Центр D находится на отрезке BC на расстоянии BD=1/3, радиус равен 1/3.';transfer='Если вместо 4 справа 6, получаем (x−1/3)²+y²=4/9. Центр остаётся тем же, новый радиус равен 2/3.';target='1/3';fresh='2/3';probe_q='Каков радиус новой окружности при правой части 6?';note='Каждая мелкая клетка соответствует 1/3 исходной единицы длины. От B до A и до C по три клетки; исходный радиус составляет одну клетку.'
        else:
            eq='AM²+BM²+CM²=50';expr='3(x²+y²)+2';reason='Получаем 3(x²+y²)+2=50, то есть x²+y²=16. Это окружность с центром B и радиусом 4.';transfer='Если сумму заменить на 2, уравнение x²+y²=0 допускает только B. Ниже 2 нет ни одной точки, потому что x²+y² неотрицательно.';target='4';fresh='1';probe_q='Сколько точек получится при новой правой части 2?';note=None
        card=entry(1070,part=part,model_note=note,question=f'Длина AC равна 2, B — середина AC. Найди все M, для которых {eq}. Определи положение центра и радиус либо назови вырождение.',answer=reason+' Обратная подстановка показывает, что каждая найденная точка удовлетворяет исходному равенству.',hint='Положи B=(0;0), A=(−1;0), C=(1;0). Запиши квадраты трёх расстояний и собери подобные члены с указанными коэффициентами.',steps=[('Запиши три квадрата','Для M=(x;y) имеем AM²=(x+1)²+y², BM²=x²+y² и CM²=(x−1)²+y². При сложении с коэффициентами подпункта левая часть равна '+expr+'.','Множитель при квадрате расстояния относится ко всей сумме квадратов.'),('Получи равносильное уравнение',reason+' Все шаги равносильны: найдена вся окружность.','Выделение полного квадрата показывает и центр, и радиус.'),('Проверь другую правую часть',transfer,'Нулевой квадрат радиуса означает одну точку, а отрицательный не даёт действительных точек.')],frames=[init,dists,full,new],cases=[dists,full,new],prompts=[('Каков радиус исходного множества в единицах длины?',target,'Отличай квадрат радиуса от самого радиуса.'),(probe_q,fresh,transfer)]);
        accepted=['1/3;1/3','1/3; 1/3','⅓;⅓'] if small else ['0;4','0; 4','B;4','B; 4','В;4','В; 4'];card['answer']=dict(mode='exact',accepted=accepted,prompt='Введи BD и радиус через точку с запятой, где D — центр найденной окружности. Если центр совпал с B, первая величина нулевая.',feedback='Сравни результат с (x−d)²+y²=r²: d задаёт положение D на BC, а для r нужен положительный квадратный корень.');rows.append(card)
    return rows


def sum_parameter():
    a={'A':(-1,0),'B':(1,0)};initial=frame('A и B симметричны относительно O',a,edges=[('A','B')]);sumview=frame('Посчитай квадраты двух расстояний',{**a,'M':(0,1)},edges=[('A','M'),('B','M')]);circle=frame('При k=2 получилась окружность',{**a,'M':(0,1)},circle=('S',(0,0),1));point=frame('При k²=2 остаётся середина',{**a,'M':(0,0)},edges=[('A','M'),('B','M')]);empty=frame('При k=1 подходящих точек нет',a,edges=[('A','B')]);different=frame('Новые AB=4 и k=4',{'A':(-2,0),'B':(2,0),'M':(0,2)},circle=('S',(0,0),4));
    card=entry(1071,question='Для данных различных A, B и числа k опиши все точки M с AM²+BM²=k². Укажи все случаи, включая единственную точку и отсутствие решений.',answer='Пусть O — середина AB, a=AB/2. Относительно O получаем OM²=k²/2−a². При k²>2a² это окружность радиуса √(k²/2−a²); при равенстве остаётся O, а при k²<2a² решений нет. Знак самого k на результат не влияет.',hint='Возьми A=(−a;0), B=(a;0). При сложении противоположные линейные члены 2ax и −2ax уничтожаются.',steps=[('Сверни сумму','При O=(0;0) оба квадрата расстояния в сумме дают (x+a)²+(x−a)²+2y²=2(x²+y²)+2a². Значит, OM²=k²/2−a².','Минимальная сумма равна 2a² и достигается именно в середине.'),('Разбери три случая','Положительная правая часть задаёт окружность; нулевая — одну точку O; отрицательная несовместна с парой действительных координат. Поскольку уравнения равносильны, это полная классификация.','Разрешать окружность любого радиуса нельзя: здесь квадрат радиуса сам зависит от k.'),('Проверь новые значения','При AB=4 и k=4 имеем a=2 и OM²=8−4=4, радиус 2. На исходном масштабе AB=2 при k²=2 остаётся O, а при k=1 точек нет. Для k=−2 результат тот же, что для +2.','Сравнивай k² с 2a², чтобы охватить и отрицательные k.')],frames=[initial,sumview,circle,different],cases=[sumview,circle,point,empty,different],prompts=[('При AB=2 и k=2 чему равен квадрат радиуса?','1','Здесь a=1: вычисли 4/2−1.'),('При AB=4 и k=4 чему равен радиус?','2','Из OM²=4 извлеки неотрицательный корень.')]);card['answer']['prompt']='Опиши три случая по знаку k²/2−a², где a=AB/2, и поясни, почему каждый даёт именно указанное множество.';return card


def difference():
    ab={'A':(0,0),'B':(4,0)};init=frame('Две исходные точки',ab,edges=[('A','B')]);sub=frame('Вычти квадраты расстояний',{**ab,'M':(3,2)},edges=[('A','M'),('B','M')]);vertical=frame('Для k=8 получается x=3',{**ab,'M':(3,2),'N':(3,-2)},line=(1,0,-3));zero=frame('Для k=−16 получается ось Oy',{**ab,'P':(0,3)},line=(1,0,0));left=frame('Для k=−24 прямая слева от A',{**ab,'P':(-1,-1)},line=(1,0,1));perp=frame('Для k=0 — серединный перпендикуляр',{**ab,'M':(2,2)},line=(1,0,-2));
    card=entry(1072,question='Для двух различных точек A, B и заданного числа k найди все M с AM²−BM²=k. Опиши положение искомой прямой для отрицательных, нулевого и положительных k.',answer='В координатах A=(0;0), B=(a;0), a=AB>0 условие равносильно 2ax−a²=k. Получается вся прямая x=(a²+k)/(2a), перпендикулярная AB. При k=0 это серединный перпендикуляр; при k=−a² — перпендикуляр через A. Значение y произвольно.',hint='Сначала вычти квадраты, не извлекая корней. Члены x² и y² должны сократиться.',steps=[('Запиши знаковую разность','AM²−BM²=x²+y²−((x−a)²+y²)=2ax−a². Знак перед скобками меняет знаки у всех их членов.','Вычитание квадратов расстояний до двух точек даёт линейное выражение.'),('Прочти целую прямую','Из равенства 2ax−a²=k следует x=(a²+k)/(2a). Ограничения на y не осталось. Все M на этой вертикали дают именно k; вне неё это равенство нарушается.','Положительное, нулевое и отрицательное k допустимы.'),('Проверь положение на оси','При a=4, k=8 получается x=3. При k=−16 — x=0, а при k=−24 — x=−1. Если k=0, выходит x=2, и все точки равноудалены от A и B.','Координата x меняется вместе с k. Прямая может лежать и вне полосы между A и B.')],frames=[init,sub,vertical,zero],cases=[sub,vertical,zero,left,perp],prompts=[('При AB=4 и k=8 чему равна абсцисса искомой прямой?','3','Вычисли (16+8)/8.'),('При AB=4 и k=−16 какова абсцисса новой прямой?','0','В числителе 16−16.')]);card['answer']['prompt']='Запиши общее уравнение прямой через а и k, укажи её направление и поясни, почему подходят все значения y.';return card


def reverse_difference():
    ab={'A':(0,0),'B':(4,0),'K':(-4,0)};init=frame('Отрази B относительно A',ab,edges=[('K','B')]);sums=frame('Испытай точку с отрицательной абсциссой',{**ab,'M':(-2,3)},edges=[('M','A'),('M','B')]);perp=frame('Серединный перпендикуляр к AK',{**ab,'M':(-2,3),'N':(-2,-1)},line=(1,0,2),edges=[('A','K')]);new=frame('Новая длина AB=6',{'A':(0,0),'B':(6,0),'K':(-6,0),'M':(-3,2)},line=(1,0,3),edges=[('A','K')]);
    card=entry(1073,question='Найди геометрическое место точек M, для которых BM²−AM²=2AB², при данных различных A и B. Построй его по отрезку AB.',answer='Пусть A=(0;0), B=(a;0). Из a²−2ax=2a² следует x=−a/2. Искомая прямая перпендикулярна AB и проходит через середину отрезка AK, где K — отражение B относительно A. Она лежит со стороны продолжения BA за A.',hint='На этот раз из BM² вычитается AM². Легко получить другую прямую, если поменять порядок.',steps=[('Вычти в требуемом порядке','BM²−AM²=(x−a)²+y²−x²−y²=a²−2ax. Например, при a=4 и M=(−2;3) получаем 45−13=32=2·4².','Знаковая разность несимметрична при перестановке A и B.'),('Построй множество без координат','Уравнение даёт x=−a/2 при любом y. В точке K, симметричной B относительно A, абсцисса −a. Значит x=−a/2 — серединный перпендикуляр к AK. Обратная подстановка выполняется вдоль всей этой прямой.','Серединный перпендикуляр задаёт и положение, и направление.'),('Измени длину','Для AB=6 отрази B относительно A. Получаются A=(0;0), K=(−6;0), середина AK=(−3;0). Искомая прямая x=−3. При M=(−3;2) разность 85−13 равна 72=2·6².','Смена длины AB переносит прямую на расстояние AB/2 от A.')],frames=[init,sums,perp,new],cases=[sums,perp,new],prompts=[('При AB=4 чему равна абсцисса середины AK?','-2','У A координата 0, у отражённой K — −4.'),('При новой длине AB=6 чему равна абсцисса всей прямой?','-3','Середина между 0 и −6 имеет отрицательную абсциссу.')]);card['answer']['prompt']='Назови прямую, укажи построение её опорной точки и проверь исходную разность для произвольного M на ней.';return card


def rectangle():
    p={'A':(0,0),'B':(4,0),'C':(4,3),'D':(0,3)};q={'A':(0,0),'B':(2,0),'C':(2,5),'D':(0,5)};sides=[('A','B'),('B','C'),('C','D'),('D','A')];init=frame('Оси вдоль сторон прямоугольника',p,edges=sides);point=frame('Точка вне отрезка BC',{**p,'M':(4,5)},edges=sides+[('M','A'),('M','D')]);all_line=frame('Вся прямая, содержащая BC',{**p,'M':(4,5),'N':(4,-2)},line=(1,0,-4),edges=sides);new=frame('Другой прямоугольник',{**q,'M':(2,-2)},line=(1,0,-2),edges=sides)
    card=entry(1074,question='В прямоугольнике ABCD найди все точки M плоскости с (AM²+DM²)−(BM²+CM²)=2AB². Выясни, ограничивается ли ответ одной стороной как отрезком.',answer='Это вся прямая BC. При A=(0;0), B=(a;0), C=(a;b), D=(0;b) левая часть равна 4ax−2a². Уравнение даёт x=a при произвольной ординате M. Обе стороны продолжения BC также содержат подходящие точки.',hint='Сгруппируй разность иначе: (AM²−BM²)+(DM²−CM²). На каждой горизонтали взаимно уничтожатся слагаемые с y.',steps=[('Рассмотри две пары вершин','Для M=(x;y) в системе осей вдоль AB и AD первая разность AM²−BM²=2ax−a². В DM²−CM² у обоих слагаемых одинаково (y−b)², поэтому получается снова 2ax−a².','Пары AB и DC равны и одинаково направлены.'),('Проверь всю прямую','4ax−2a²=2a² равносильно x=a, потому что a>0. Значение y свободно. Для прямоугольника 4 на 3 точка M=(4;5) вне отрезка BC даёт 41+20−25−4=32=2·4².','Из условия на x нельзя выводить несуществующее ограничение 0≤y≤b.'),('Измени размеры','При AB=2 и AD=5 искомая прямая x=2. Для M=(2;−2) получаются AM²=8, DM²=53, BM²=4, CM²=49: разность 8=2·2².','Высота прямоугольника сократилась, но вершины B и C по-прежнему задают прямую ответа.')],frames=[init,point,all_line,new],cases=[point,all_line,new],prompts=[('В исходном примере с AB=4 чему равна требуемая разность квадратов?','32','Вычисли 2·4².'),('При AB=2 и AD=5 чему равна абсцисса всей новой прямой?','2','Прямая проходит через B и C.')]);card['answer']=dict(mode='exact',accepted=['прямая BC','прямая CB','прямая ВС','прямая СВ','вся прямая BC','вся прямая ВС','BC','CB','ВС','СВ'],prompt='Назови прямую ответа по двум вершинам. Слово «прямая» можно написать перед буквами.',feedback='Из уравнения следует x=a без ограничения на y. Отрезок и луч не охватывают все решения; найди две вершины с абсциссой a.');return card


def rhombus():
    p={'A':(-3,0),'B':(0,2),'C':(3,0),'D':(0,-2)};q={'A':(-2,0),'B':(0,3),'C':(2,0),'D':(0,-3)};edges=[('A','B'),('B','C'),('C','D'),('D','A')];initial=frame('Выбери оси по диагоналям',p,edges=edges+[('A','C'),('B','D')]);sample=frame('Проверь одну точку на новой прямой',{**p,'M':(2,-3)},edges=edges+[('A','M'),('C','M')]);all_line=frame('Прямая через центр ромба',{**p,'M':(2,-3),'N':(-2,3)},line=(3,2,0),edges=edges);new=frame('Поменяй длины диагоналей',{**q,'M':(3,-2)},line=(2,3,0),edges=edges)
    card=entry(1075,question='Диагонали ромба ABCD равны 2a и 2b. Найди множество M, для которых AM²+DM²=BM²+CM². Укажи, к какой именно стороне перпендикулярна искомая прямая.',answer='Возьмём A=(−a;0), B=(0;b), C=(a;0), D=(0;−b). Тогда равенство сводится к 4ax+4by=0. Ответ — вся прямая через точку пересечения диагоналей, перпендикулярная AB (и параллельной ей CD).',hint='Вычти квадраты расстояний до противоположных вершин A,C и до D,B. В каждой разности сократятся квадраты переменных.',steps=[('Сгруппируй по диагоналям','AM²−CM²=(x+a)²−(x−a)²=4ax. Аналогично DM²−BM²=(y+b)²−(y−b)²=4by. Исходное условие равносильно их нулевой сумме.','Симметричные координаты концов диагоналей оставляют только линейные члены.'),('Определи направление и обоснуй обратное','Уравнение ax+by=0 проходит через O, где x=y=0. Проверь перпендикулярность по теореме Пифагора: положи T=(a;b) и P=(b;−a). Тогда OT параллельна AB, P лежит на найденной прямой, OT²=OP²=a²+b², а TP²=(a−b)²+(a+b)²=2(a²+b²). Поэтому OP перпендикулярна OT и AB. Все преобразования равносильны.','Перпендикулярность относится к AB и CD. При ромбе, не являющемся квадратом, диагональ обычно не удовлетворяет требованию.'),('Измени отношение диагоналей','При a=3, b=2 получается 3x+2y=0, ей принадлежит M=(2;−3). При a=2, b=3 получаем 2x+3y=0, и на ней M=(3;−2). Её наклон меняется вместе со стороной AB.','Подставь координаты новой точки как в линейное равенство, так и в исходную сумму квадратов.')],frames=[initial,sample,all_line,new],cases=[sample,all_line,new],prompts=[('При a=3, b=2 и x=2 чему равно y на исходной прямой?','-3','Из 6+2y=0 найди y.'),('При новых a=2, b=3 и x=3 чему равно y?','-2','Подставь в 2x+3y=0.')]);card['answer']['prompt']='Опиши положение прямой по центру ромба и конкретной стороне, выведи её уравнение и обоснуй оба направления.';return card


def build():return {'bookId':BOOK,'lessons':[apollonius()]+weighted_sums()+[sum_parameter(),difference(),reverse_difference(),rectangle(),rhombus()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args();s=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert OUT.read_text()==s
    else:OUT.write_text(s)
